package io.dndroll.domain;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class RestabilizationEffectTest {
 final UUID attempt=UUID.fromString("10000000-0000-0000-0000-000000000001");final CharacterSheet helper=CharacterSheet.empty("New helper");
 CharacterSheet before(){var s=CharacterSheet.empty("Target");var b=s.combat();return s.change(s.name(),new CharacterSheet.Combat(12,0,7,b.speed(),1,2,b.acMode(),b.manualAc(),b.source()),s.resources(),List.of(),s.overrides());}
 CharacterSheet.Condition unconscious(){return StabilizationEffect.plan(before(),helper,attempt,true,true,true,20).annotations().get(1);}
 CharacterSheet unstable(int failures,int temp){var s=before();var b=s.combat();return s.change(s.name(),new CharacterSheet.Combat(12,0,temp,b.speed(),0,failures,b.acMode(),b.manualAc(),b.source()),s.resources(),List.of(unconscious()),s.overrides());}
 RestabilizationEffect.Plan plan(CharacterSheet s,int total){return RestabilizationEffect.plan(s,helper,unconscious(),attempt,true,true,true,true,total);}
 void manual(RestabilizationEffect.Plan p,String reason){assertEquals("MANUAL_REQUIRED",p.status());assertTrue(p.reasons().contains(reason),p.reasons().toString());assertNull(p.hp());assertTrue(p.annotations().isEmpty());}
 @Test void successfulNewCheckResetsBothCountsWithoutHealingOrReplacingOriginalUnconscious(){for(int failed:List.of(1,2)){var s=unstable(failed,4);var p=plan(s,10);assertEquals("CANDIDATE",p.status());assertEquals(0,p.hp());assertEquals(4,p.tempHp());assertEquals(0,p.deathSuccesses());assertEquals(0,p.deathFailures());assertEquals(2,p.annotations().size());assertEquals(unconscious(),p.annotations().get(1));assertEquals("a19-stable:"+attempt,p.annotations().getFirst().id());assertEquals(unstable(failed,4),s);}}
 @Test void failedChecksAndMissingBindingHaveNoExecutableValues(){manual(plan(unstable(1,0),9),"RESTABILIZATION_CHECK_FAILED");manual(RestabilizationEffect.plan(unstable(1,0),helper,unconscious(),attempt,true,true,true,false,20),"BOUND_RESTABILIZATION_CHECK_REQUIRED");}
 @Test void originReviewAndDistinctHelperCannotBeBypassed(){manual(RestabilizationEffect.plan(unstable(1,0),helper,unconscious(),attempt,false,true,true,true,20),"UNCHANGED_DAMAGE_ORIGIN_REQUIRED");manual(RestabilizationEffect.plan(unstable(1,0),helper,unconscious(),attempt,true,false,true,true,20),"ORDINARY_HELP_REVIEW_REQUIRED");manual(RestabilizationEffect.plan(unstable(1,0),helper,unconscious(),attempt,true,true,false,true,20),"DISTINCT_HELPER_REQUIRED");}
 @Test void exactRetainedRecordOnlyIsRequired(){var s=unstable(1,0);manual(RestabilizationEffect.plan(s,helper,null,attempt,true,true,true,true,20),"ORIGINAL_UNCONSCIOUS_ONLY_REQUIRED");manual(plan(s.change(s.name(),s.combat(),s.resources(),List.of(),s.overrides()),20),"ORIGINAL_UNCONSCIOUS_ONLY_REQUIRED");var extra=new ArrayList<>(s.conditions());extra.add(new CharacterSheet.Condition("other","Other","","Other",unconscious().source(),null,null));manual(plan(s.change(s.name(),s.combat(),s.resources(),extra,s.overrides()),20),"ORIGINAL_UNCONSCIOUS_ONLY_REQUIRED");}
 @Test void zeroFailuresThreeFailuresPositiveHpAndAdjustmentsAreManual(){for(int f:List.of(0,3))manual(plan(unstable(f,0),20),"UNSTABLE_VALUES_REQUIRED");var s=unstable(1,0);var b=s.combat();manual(plan(s.change(s.name(),new CharacterSheet.Combat(12,1,0,b.speed(),0,1,b.acMode(),b.manualAc(),b.source()),s.resources(),s.conditions(),s.overrides()),20),"UNSTABLE_VALUES_REQUIRED");manual(plan(s.change(s.name(),b,s.resources(),s.conditions(),List.of(new CharacterSheet.Override("ac",20,"test"))),20),"TARGET_ADJUSTMENTS_REQUIRE_MANUAL");}
 @Test void helperMustSupportOrdinaryMedicineButProficiencyIsNotRequired(){assertEquals("CANDIDATE",plan(unstable(1,0),20).status());manual(RestabilizationEffect.plan(unstable(1,0),null,unconscious(),attempt,true,true,true,true,20),"SUPPORTED_RESTABILIZATION_HELPER_REQUIRED");}
 @Test void inputsAreValidated(){assertThrows(DomainException.class,()->plan(null,20));assertThrows(DomainException.class,()->RestabilizationEffect.plan(unstable(1,0),helper,unconscious(),null,true,true,true,true,20));}
 @Test void plansAreDeterministicImmutableAndNewStableIdentityIsAttemptScoped(){var p=plan(unstable(1,4),20);assertEquals(2,p.annotations().size());assertEquals(p,plan(unstable(1,4),20));assertThrows(UnsupportedOperationException.class,()->p.annotations().clear());assertThrows(UnsupportedOperationException.class,()->p.reasons().add("x"));assertNotEquals(p.annotations().getFirst(),RestabilizationEffect.plan(unstable(1,4),helper,unconscious(),UUID.randomUUID(),true,true,true,true,20).annotations().getFirst());}
}
